mapper.select:
SELECT sc.id, s.name as studentName, s.id as studentId, c.name as courseName, c.lesson_type as courseType, cl.name as className, sc.amount as actualAmount, sc.verify_state as status, sc.add_time as enrollmentTime, sc.remark FROM student_course sc LEFT JOIN student s ON sc.student_id = s.id LEFT JOIN course c ON sc.course_id = c.id LEFT JOIN class cl ON sc.course_id = cl.course_id AND cl.deleted = 0 WHERE sc.deleted = 0
AND s.name LIKE CONCAT('%', #{studentName}, '%')
AND EXISTS (SELECT 1 FROM user u WHERE u.id = s.user_id AND u.mobile LIKE CONCAT('%', #{studentPhone}, '%'))
AND sc.course_id = #{courseId}
AND cl.id = #{classId}
AND sc.verify_state = #{status}
AND DATE(sc.add_time) >= #{startDate}
AND DATE(sc.add_time) <= #{endDate}
ORDER BY sc.add_time DESC

SELECT sc.id, s.id as studentId, s.name as studentName, c.id as courseId, c.name as courseName, cl.id as classId, cl.name as className, sc.add_time as enrollmentTime, sc.verify_state as status, sc.amount as fee, sc.paid_amount as paidAmount, sc.remark FROM student_course sc LEFT JOIN student s ON sc.student_id = s.id LEFT JOIN course c ON sc.course_id = c.id LEFT JOIN class cl ON sc.course_id = cl.course_id AND cl.deleted = 0 WHERE sc.deleted = 0 AND DATE_FORMAT(sc.add_time, '%Y-%m') = #{yearMonth}
AND sc.course_id = #{courseId}
ORDER BY sc.add_time DESC
